 -->\n\n  <!-- blockdef:tm1637 -->\n  <category name=\"4 Digit Display\">\n    <label text=\"TM1637 Display\"></label>\n    <label text=\"Library: https://github.com/mcauser/micropython-tm1637\"></label>\n    <button text=\"Install tm1637 library\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"tm1637_init\">\n      <value name=\"clk\">\n        <shadow type=\"pinout\">\n          <field name=\"PIN\">18</field>\n        </shadow>\n      </value>\n      <value name=\"dio\">\n        <shadow type=\"pinout\">\n          <field name=\"PIN\">17</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_write_char\">\n      <value name=\"character\">\n        <shadow type=\"text\">\n          <field name=\"TEXT\">A</field>\n        </shadow>\n      </value>\n      <value name=\"position\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">0</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_write_text\">\n      <value name=\"text\">\n        <shadow type=\"text\">\n          <field name=\"TEXT\">bipe</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_scroll_text\">\n      <value name=\"text\">\n        <shadow type=\"text\">\n          <field name=\"TEXT\">hello world</field>\n        </shadow>\n      </value>\n      <value name=\"speed\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">200</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_set_time\">\n      <value name=\"hour\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">12</field>\n        </shadow>\n      </value>\n      <value name=\"minute\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">0</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_set_temperature\">\n      <value name=\"temperature\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">20</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_set_brightness\">\n      <value name=\"brightness\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">7</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"tm1637_clear\"></block>\n  </category>\n  <!-- /blockdef:tm1637 -->\n  </category>\n\n  <category name=\"%{BKY_CAT_SENSORS}\">\n\n    <category name=\"%{BKY_CAT_TEMP_HUMI}\">\n      <label text=\"DHT11/22 Temperature and Humidity Sensor\"></label>\n      <block type=\"dht_init\">\n        <field name=\"BLOCK_DHT_INIT\">Start DHT11/22 sensor</field>\n        <value name=\"pin\">\n          <shadow type=\"pinout\">\n            <field name=\"PIN\"></field>\n          </shadow>\n        </value>\n      </block>\n      <block type=\"dht_measure\"></block>\n      <block type=\"dht_read_temp\"></block>\n      <block type=\"dht_read_humidity\"></block>\n\n      <label text=\"SHT20 I2C Temperature and Humidity Sensor\"></label>\n\n      <block type=\"sht20_init\">\n\t      <value name=\"scl\">\n\t\t<shadow type=\"math_number\">\n\t\t  <field name=\"NUM\">22</field>\n\t\t</shadow>\n\t      </value>\n\t      <value name=\"sda\">\n\t\t<shadow type=\"math_number\">\n\t\t  <field name=\"NUM\">21</field>\n\t\t</shadow>\n\t      </value>\n      </block>\n\n    <block type=\"sht20_temperature\"> </block>\n    <block type=\"sht20_humidity\"> </block>\n\n    </category>\n\n\n<!--Adicionando os blocos do Anenm\u00f4metro-->\n    <!-- blockdef:anemometro -->\n    <category name=\"Anem\u00f4metro\">\n      <label text=\"Anen\u00f4metro\"></label>\n\n      <block type=\"anemo_init\">\n        <value name=\"Fun\u00e7\u00e3o\">\n          <shadow type=\"text\">\n            <field name=\"TEXT\"></field>\n          </shadow>\n        </value>\n        <value name=\"pin\">\n          <shadow type=\"pinout\"></shadow>\n        </value>\n      </block>\n\n      <block type=\"anemo_stop\">\n        <value name=\"Fun\u00e7\u00e3o\">\n          <shadow type=\"text\">\n            <field name=\"TEXT\"></field>\n          </shadow>\n        </value>\n      </block>\n    </category>\n    <!-- /blockdef:anemometro -->\n<!--Adicionando os blocos do Pluvi\u00f4metro--> \n  <!-- blockdef:pluviometro -->\n  <category name=\"Pluvi\u00f4metro\">\n    <label text=\"Pluvi\u00f4metro\"></label>\n\n    <block type=\"pluvio_init\">\n      <value name=\"Fun\u00e7\u00e3o\">\n        <shadow type=\"text\">\n          <field name=\"TEXT\"></field>\n        </shadow>\n      </value>\n      <value name=\"pin\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n    </block>\n\n    <block type=\"pluvio_stop\">\n      <value name=\"Fun\u00e7\u00e3o\">\n        <shadow type=\"text\">\n          <field name=\"TEXT\"></field>\n        </shadow>\n      </value>\n    </block>\n  </category>\n  <!-- /blockdef:pluviometro -->\n\n  <!-- blockdef:hcsr04 -->\n  <category name=\"%{BKY_CAT_ULTRASOUND}\">\n    <label text=\"HCSR04 ultrasound distance sensor\"></label>\n    <label text=\"Library: https://github.com/rsc1975/micropython-hcsr04\"></label>\n    <button text=\"Install HCSR04 library\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"hcsr_init\">\n      <value name=\"echo\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n      <value name=\"trigger\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n      <value name=\"timeout\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">10000</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"hcsr_read\"></block>\n  </category>\n  <!-- /blockdef:hcsr04 -->\n\n  <!-- blockdef:gps -->\n  <category name=\"GPS\">\n    <label text=\"Global Positioning System (GPS) sensor\"></label>\n    <label text=\"Library: https://github.com/rafaelaroca/mini_micropyGPS\"></label>\n    <button text=\"Install mini_micropyGPS library\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"gps_init\">\n      <value name=\"uart\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">2</field>\n        </shadow>\n      </value>\n      <value name=\"tx\">\n        <shadow type=\"pinout\">\n          <field name=\"PIN\">17</field>\n        </shadow>\n      </value>\n      <value name=\"rx\">\n        <shadow type=\"pinout\">\n          <field name=\"PIN\">16</field>\n        </shadow>\n      </value>\n      <value name=\"bps\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">38400</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"gps_update\"></block>\n\n    <block type=\"gps_coord_format\"></block>\n\n    <block type=\"gps_get_lat\"></block>\n\n    <block type=\"gps_get_long\"></block>\n\n    <block type=\"gps_get_height\"></block>\n\n    <block type=\"gps_get_speed\"></block>\n\n    <block type=\"gps_get_date\"></block>\n\n    <block type=\"gps_get_time\"></block>\n  </category>\n  <!-- /blockdef:gps -->\n\n  <!-- blockdef:max30100 -->\n  <category name=\"Oximeter\">\n    <label text=\"MAX30100 pulse oximeter sensor\"></label>\n    <label text=\"Library: https://github.com/\"></label>\n    <button text=\"Install MAX30100 library\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"max30100_init\">\n      <value name=\"i2c\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">0</field>\n        </shadow>\n      </value>\n      <value name=\"scl\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n      <value name=\"sda\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n    </block>\n\n    <block type=\"max30100_read\"></block>\n\n    <block type=\"max30100_red\"></block>\n\n    <block type=\"max30100_ir\"></block>\n  </category>\n  <!-- /blockdef:max30100 -->\n\n  <!-- blockdef:bmp -->\n  <category name=\"%{BKY_CAT_PRESS}\">\n\n    <label text=\"BMP180\"></label>\n\n    <label text=\"Library: https://github.com/micropython-IMU/micropython-bmp180\"></label>\n\n    <button text=\"Install bmp180 library (BMP180)\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"bmp180_init\">\n      <value name=\"scl\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">5</field>\n        </shadow>\n      </value>\n      <value name=\"sda\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">4</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"bmp180_temperature\"></block>\n\n    <block type=\"bmp180_pressure\"></block>\n\n    <block type=\"bmp180_altitude\"></block>\n\n    <label text=\"BMP280\"></label>\n\n    <label text=\"Library: \"></label>\n\n    <button text=\"Install bmp280 library (BMP280)\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"bmp280_init\">\n      <value name=\"scl\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">22</field>\n        </shadow>\n      </value>\n      <value name=\"sda\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">21</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"bmp280_measure\"></block>\n\n    <block type=\"bmp280_sleep\"></block>\n\n    <block type=\"bmp280_temperature\"></block>\n\n    <block type=\"bmp280_pressure\"></block>\n  </category>\n  <!-- /blockdef:bmp -->\n\n  <!-- blockdef:ccs811 -->\n  <category name=\"%{BKY_CAT_AIR}\">\n    <label text=\"CCS811\"></label>\n    <label text=\"Library: https://github.com/Notthemarsian/CCS811\"></label>\n    <button text=\"Install CCS811 library\" callbackKey=\"installPyLib\"></button>\n\n    <block type=\"ccs811_init\">\n      <value name=\"scl\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">22</field>\n        </shadow>\n      </value>\n      <value name=\"sda\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">21</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"ccs811_data_ready\"></block>\n\n    <block type=\"ccs811_eCO2\"></block>\n\n    <block type=\"ccs811_tVOC\"></block>\n  </category>\n  <!-- /blockdef:ccs811 -->\n\n  <category name=\"%{BKY_CAT_IMU}\">\n\t<label text=\"MPU6050 IMU\"></label>\n\t<label text=\"Library: https://github.com/\"></label>\n\t<button text=\"Install imu library (MPU6050)\" callbackKey=\"installPyLib\"></button>\n\t<button text=\"Load example: mpu6050\" callbackKey=\"loadExample\"></button>\n\t<button text=\"Documentation and how to connect: mpu6050\" callbackKey=\"loadDoc\"></button>\n\n\t<block type=\"init_mpu6050\">\n\t\t<value name=\"scl\">\n\t\t<shadow type=\"math_number\">\n\t\t<field name=\"NUM\">5</field>\n\t\t</shadow>\n\t\t</value>\n\t\t<value name=\"sda\">\n\t\t<shadow type=\"math_number\">\n\t\t<field name=\"NUM\">4</field>\n\t\t</shadow>\n\t\t</value>\n\t</block>\n\n\t<block type=\"mpu6050_read_acc_x\"> </block>\n\t<block type=\"mpu6050_read_acc_y\"> </block>\n\t<block type=\"mpu6050_read_acc_z\"> </block>\n\n\t<block type=\"mpu6050_read_gyro_x\"> </block>\n\t<block type=\"mpu6050_read_gyro_y\"> </block>\n\t<block type=\"mpu6050_read_gyro_z\"> </block>\n\n\t<label text=\"MPU9250 IMU\"></label>\n\t<button text=\"Install mpu9250 library\" callbackKey=\"installPyLib\"></button>\n\t<button text=\"Install mpu6500 library\" callbackKey=\"installPyLib\"></button>\n\t<button text=\"Install ak8963 library\" callbackKey=\"installPyLib\"></button>\n\n\t<block type=\"mpu9250_init\">\n\t\t<value name=\"scl\">\n\t\t<shadow type=\"math_number\">\n\t\t<field name=\"NUM\">22</field>\n\t\t</shadow>\n\t\t</value>\n\t\t<value name=\"sda\">\n\t\t<shadow type=\"math_number\">\n\t\t<field name=\"NUM\">21</field>\n\t\t</shadow>\n\t\t</value>\n\t</block>\n\n\t<block type=\"mpu9250_acc\"> </block>\n\t<block type=\"mpu9250_gyro\"> </block>\n\t<block type=\"mpu9250_mag\"> </block>\n\t<block type=\"mpu9250_temp\"> </block>\n\n  </category>\n\n      <!-- blockdef:ds18x20 -->\n      <category name=\"OneWire\">\n        <label text=\"OneWire\"></label>\n        <button text=\"Load example: ds1820\" callbackKey=\"loadExample\"></button>\n        <button text=\"Documentation and how to connect: ds1820\" callbackKey=\"loadDoc\"></button>\n\n        <block type=\"onewire_ds18x20_init\">\n          <value name=\"pin\">\n            <shadow type=\"pinout\"></shadow>\n          </value>\n        </block>\n\n        <block type=\"onewire_ds18x20_scan\"></block>\n\n        <block type=\"onewire_ds18x20_convert\"></block>\n\n        <block type=\"onewire_ds18x20_read_temp\">\n          <value name=\"rom\">\n            <shadow type=\"math_number\">\n              <field name=\"NUM\">10000</field>\n            </shadow>\n          </value>\n        </block>\n      </category>\n      <!-- /blockdef:ds18x20 -->\n\n\n  <category name=\"RFID Reader\">\n      <label text=\"RC522 13.56MHz RFID Reader\"></label>\n      <label text=\"Library: https://github.com/wendlers/micropython-mfrc522\"></label>\n        <button text=\"Install mfrc522 library\" callbackKey=\"installPyLib\"></button>\n        <button text=\"Load example: mfrc522\" callbackKey=\"loadExample\"></button>\n        <button text=\"Documentation and how to connect: mfrc522\" callbackKey=\"loadDoc\"></button>\n\n      <block type=\"rfid_rc522_init\">\n        <value name=\"sck\">\n          <shadow type=\"pinout\">\n            <field name=\"SCK\"></field>\n          </shadow>\n        </value>\n \n        <value name=\"mosi\">\n          <shadow type=\"pinout\">\n            <field name=\"MOSI\"></field>\n          </shadow>\n        </value>\n\n         <value name=\"miso\">\n          <shadow type=\"pinout\">\n            <field name=\"MISO\"></field>\n          </shadow>\n        </value>\n \n        <value name=\"rst\">\n          <shadow type=\"pinout\">\n            <field name=\"RST\"></field>\n          </shadow>\n        </value>\n \n        <value name=\"cs\">\n          <shadow type=\"pinout\">\n            <field name=\"RST\"></field>\n          </shadow>\n        </value>\n\n      </block>\n      <block type=\"rfid_rc522_detect_card\"></block>\n      <block type=\"rfid_rc522_anticoll\"></block>\n      <block type=\"rfid_rc522_read_card\"></block>\n      <block type=\"rfid_rc522_write_card\"></block>\n\n  </category>\n\n\n  <!-- blockdef:encoder -->\n  <category name=\"Rotatory Encoder\">\n    <label text=\"Rotatory Incremental Encoder\"></label>\n    <button text=\"Load example: encoder\" callbackKey=\"loadExample\"></button>\n    <button text=\"Documentation and how to connect: encoder\" callbackKey=\"loadDoc\"></button>\n\n    <block type=\"encoder_init\">\n      <value name=\"p0\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n      <value name=\"p1\">\n        <shadow type=\"pinout\"></shadow>\n      </value>\n    </block>\n\n    <block type=\"encoder_reset\"></block>\n\n    <block type=\"encoder_read\"></block>\n  </category>\n  <!-- /blockdef:encoder -->\n\n  <!-- blockdef:esp32cam -->\n  <category name=\"Camera (ESP32CAM)\">\n    <label text=\"OV2640 Camera on ESP32-CAM Board\"></label>\n    <label text=\"More info: https://rafaelaroca.wordpress.com/2021/07/15/esp32-camera-micropython-and-no-esptool/\"></label>\n    <button text=\"Load example: esp32cam\" callbackKey=\"loadExample\"></button>\n\n    <block type=\"esp32_cam_init\"></block>\n\n    <block type=\"esp32_cam_capture\"></block>\n\n    <block type=\"esp32_cam_red_led\">\n      <value name=\"value\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">1</field>\n        </shadow>\n      </value>\n    </block>\n\n    <block type=\"esp32_cam_white_led\">\n      <value name=\"value\">\n        <shadow type=\"math_number\">\n          <field name=\"NUM\">1</field>\n        </shadow>\n      </value>\n    </block>\n  </category>\n  <!-- /blockdef:esp32cam -->\n  </category>\n\n  <category name=\"%{BKY_CAT_OUTPUTS}\">\n    <category name=\"Relay\">\n      <label text=\"Relay\"></label>\n      <block type=\"relay_switch\">\n        <value name=\"pin\">\n          <shadow type=\"pinout\">\n            <field name=\"PIN\"></field>\n          </shadow>\n        </value>\n      </block>\n    </category>\n\n    <!-- blockdef:mcp23017 -->\n    <category name=\"I/O Expander\">\n      <label text=\"I/O Expander\"></label>\n      <label text=\"MCP23017\"></label>\n      <label text=\"Library source: https://github.com/ShrimpingIt/micropython-mcp230xx/blob/master/mcp.py \"></label>\n      <button text=\"Install mcp23017 library\" callbackKey=\"installPyLib\"></button>\n\n      <block type=\"mcp23017_init\">\n        <value name=\"scl\">\n          <shadow type=\"math_number\">\n            <field name=\"NUM\">22</field>\n          </shadow>\n        </value>\n        <value name=\"sda\">\n          <shadow type=\"math_number\">\n            <field name=\"NUM\">21</field>\n          </shadow>\n        </value>\n      </block>\n\n      <block type=\"mcp23017_setup\">\n        <value name=\"pin\">\n          <shadow type=\"math_number\">\n            <field name=\"NUM\">0</field>\n          </shadow>\n        </value>\n      </block>\n\n      <block type=\"mcp23017_output\">\n        <value name=\"pin\">\n          <shadow type=\"math_number\">\n            <field name=\"NUM\">0</field>\n          </shadow>\n        </value>\n      </block>\n\n      <block type=\"mcp23017_input\">\n        <value name=\"pin\">\n          <shadow type=\"math_number\">\n            <field name=\"NUM\">0</field>\n          </shadow>\n        </value>\n      </block>\n    </category>\n    <!-- /blockdef:mcp23017 -->\n\n\n  <category name=\"RC Servo Motor\">\n      <label text=\"Hobby RC Servo Motor\"></label>\n    <block type=\"init_servo\">\n        <value name=\"pin\">\n          <shadow type=\"pinout\">\n            <field name=\"PIN\"></field>\n          </shadow>\n        </value>\n    </block>\n\n    <block type=\"move_servo\">\n    <value name=\"angle\">\n        <shadow type=\"math_numb